#!/bin/bash
# 10 — HƯNG CHẠY SAU KHI DUYỆT proposal.diff. Áp đề xuất AGENTS.md + SOUL.md Hungreo (Q1=A, Q3 mục 1–6, 09/10).
# Chỉ ghi 2 file workspace; không restart, không đổi config. Abort nếu base đã đổi (Rùa sửa sau 09/10 ~14:00).
# Chạy: ssh -i ~/.ssh/hostinger_kvm2 hung@72.61.123.33 'bash -s' < 10_apply.sh   → rồi /new trong DM Rùa.
set -euo pipefail
trap 'echo "FAILED ở dòng $LINENO — gửi output cho Claude Code"' ERR
W=/home/hung/.openclaw-hungreo/workspace
SUF=bak-20261009-pre-admin-suckhoe
NEW_AGENTS=05de36e75d226832dbf77e9edd020c8420197051451fb7162a183ee4bb8b9ea6
NEW_SOUL=461604b328efa8d6ab129def27e32362d815e4dc116224012d65e8120b29547c
S=$(mktemp -d /tmp/rua-proposal-XXXX); trap 'rm -rf "$S"' EXIT
base64 -d > "$S/changes.py" <<'B64'

B64
python3 -I - "$S" "$W" "$SUF" "$NEW_AGENTS" "$NEW_SOUL" <<'PY'
import sys, hashlib, importlib.util, os, shutil, pathlib
S, W, SUF, NA, NS = sys.argv[1], pathlib.Path(sys.argv[2]), sys.argv[3], sys.argv[4], sys.argv[5]
spec = importlib.util.spec_from_file_location("changes", f"{S}/changes.py"); c = importlib.util.module_from_spec(spec); spec.loader.exec_module(c)
want = {"AGENTS.md": NA, "SOUL.md": NS}
h = lambda b: hashlib.sha256(b).hexdigest()
for n in want:
    cur = h((W / n).read_bytes())
    if cur == want[n]: print(f"{n}: đã áp từ trước"); continue
    if cur != c.BASE_SHA[n]: raise SystemExit(f"ABORT {n}: base đã đổi ({cur[:12]}) — báo Claude Code soạn lại diff")
for n in want:
    f = W / n
    if h(f.read_bytes()) == want[n]: continue
    bak = W / f"{n}.{SUF}"
    if not bak.exists(): shutil.copy2(f, bak)
    assert h(bak.read_bytes()) == c.BASE_SHA[n]
    new = c.apply(n, f.read_text(encoding="utf-8")).encode("utf-8")
    assert h(new) == want[n], f"{n}: hash kết quả lệch"
    tmp = W / f".{n}.new.{os.getpid()}"; tmp.write_bytes(new); shutil.copymode(f, tmp); os.replace(tmp, f)
    print(f"{n}: OK {len(new.decode())} chars, backup {bak.name}")
for n in want: assert h((W / n).read_bytes()) == want[n]
print("OK 10 — readback hash khớp. Bước tiếp: gửi /new trong DM Rùa, rồi hỏi Rùa: 'Theo AGENTS.md, phạm vi admin Suckhoe của em gồm gì?'")
PY
